-- PT103-S2-Q2. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT103-S2-Q2$batch07$ AND q.stimulus=$batch07$Once a child’s imagination becomes developed, a host of imaginary creatures may torment the child. But this newly developed cognitive capacity may also be used to render these creatures harmless. For instance, a child’s new toy may be imagined as an ally, powerful enough to ward off any imaginary threats.$batch07$ AND q.prompt=$batch07$The type of situation described above most closely conforms to which one of the following propositions?$batch07$ AND q.correct_choice=$batch07$B$batch07$) THEN RAISE EXCEPTION 'Question changed: PT103-S2-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT103-S2-Q2$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT103-S2-Q2'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT103-S2-Q2$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Statements$batch07$, $batch07$Once a child's imagination develops, imaginary creatures may torment the child. But the same new capacity can make those creatures harmless, for instance by imagining a toy as a powerful ally.$batch07$), (1, $batch07$Evaluate$batch07$, $batch07$Pause and infer. One thing, a developed imagination, causes the problem (the scary creatures) and also solves it (the imaginary ally). The "But" and "this newly developed cognitive capacity" tie both halves to the same source.$batch07$), (2, $batch07$Goal$batch07$, $batch07$A general principle: the thing that causes a problem can also fix it.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT103-S2-Q2$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$The passage shows a new capacity that does more than cause problems. It also solves them.$batch07$), ($batch07$B$batch07$, $batch07$Imagination causes the torment and also supplies the cure. "Sometimes" and "may" keep it as modest as the one example.$batch07$), ($batch07$C$batch07$, $batch07$The passage never says children can't tell real threats from imaginary ones.$batch07$), ($batch07$D$batch07$, $batch07$Acknowledging fears never comes up, and "most effective" is a comparison the passage can't support.$batch07$), ($batch07$E$batch07$, $batch07$One example about imaginary creatures can't support a claim about *most* child-rearing problems.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT103-S2-Q2$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
